public class FloydWarshall {
    static final int INF = Integer.MAX_VALUE / 2;

    public static void floyd(int[][] dist, int n) {
        // dist[i][j] = shortest distance from i to j
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    dist[i][j] = Math.min(dist[i][j], 
                        dist[i][k] + dist[k][j]);
                }
            }
        }
    }
}
