const INF = Number.MAX_VALUE;

function floydWarshall(dist, n) {
    // dist is n×n adjacency matrix
    for (let k = 0; k < n; k++) {
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                dist[i][j] = Math.min(
                    dist[i][j],
                    dist[i][k] + dist[k][j]
